import { useEffect, useState } from 'react';
import { useStore } from '../context/StoreContext';
import { productApi } from '../services/api';
import ProductCard from '../components/ProductCard';

function DashboardPage() {
  const { wishlist, cart } = useStore();
  const [picks, setPicks] = useState([]);

  useEffect(() => {
    productApi.getRecommendations({ query: 'laptop', usage: 'study', budget: 150000 }).then((data) => setPicks(data.products || [])).catch(() => setPicks([]));
  }, []);

  return (
    <section className="section">
      <div className="container" style={{ display: 'grid', gridTemplateColumns: '260px 1fr', gap: 22, alignItems: 'start' }}>
        <aside className="card" style={{ padding: 22, position: 'sticky', top: 100 }}>
          <div style={{ textAlign: 'center', marginBottom: 18 }}>
            <div style={{ width: 70, height: 70, borderRadius: '50%', display: 'grid', placeItems: 'center', margin: '0 auto 12px', background: 'var(--brand)', color: 'white', fontWeight: 900 }}>MU</div>
            <h3 style={{ margin: 0 }}>Muhammad User</h3>
            <p className="subtitle" style={{ margin: '6px 0 0' }}>techstore.user@email.com</p>
          </div>
          {['My Orders', 'Wishlist', 'Saved Addresses', 'Notifications', 'AI Picks', 'Account Settings', 'Logout'].map((item) => (
            <button className="btn btn-secondary" style={{ width: '100%', marginBottom: 8 }} key={item} type="button">{item}</button>
          ))}
        </aside>

        <div>
          <div className="section-header">
            <div>
              <span className="eyebrow">User dashboard</span>
              <h1 className="title">Account overview</h1>
            </div>
          </div>

          <div className="grid grid-3">
            <div className="card" style={{ padding: 20 }}><small className="subtitle">Total Orders</small><h2>14</h2></div>
            <div className="card" style={{ padding: 20 }}><small className="subtitle">Wishlist Items</small><h2>{wishlist.length}</h2></div>
            <div className="card" style={{ padding: 20 }}><small className="subtitle">Cart Items</small><h2>{cart.length}</h2></div>
          </div>

          <div className="card" style={{ padding: 22, marginTop: 20 }}>
            <h3>Recent Orders</h3>
            <div style={{ display: 'grid', gap: 10 }}>
              <div className="badge">#TS-0042 · ASUS ROG Strix · In Transit · $999</div>
              <div className="badge">#TS-0041 · AirPods Pro · Delivered · $249</div>
              <div className="badge">#TS-0040 · WD Black SSD · Processing · $129</div>
            </div>
          </div>

          <div className="section-header" style={{ marginTop: 30 }}>
            <div>
              <span className="eyebrow">AI personalized recommendations</span>
              <h2 className="title">Products selected by Python AI</h2>
            </div>
          </div>
          <div className="grid grid-4">
            {picks.length === 0
              ? Array.from({ length: 4 }).map((_, index) => <div className="loading-skeleton" style={{ height: 320 }} key={index} />)
              : picks.map((product) => <ProductCard key={product.id || product.productId} product={product} />)}
          </div>
        </div>
      </div>
    </section>
  );
}

export default DashboardPage;
